func tryToMergeLastTwoEdits(hl *HList) {
	editsL, elemsL := hl.NDoneBack(2)
	if len(editsL) != 2 {
		return
	}
	if insertConsecutiveLetters(editsL[0], editsL[1]) ||
		consecutiveSpaces(editsL[0], editsL[1]) {
		hl.mergeToDoneBack(elemsL[0])
	}
}

