func insertConsecutiveLetters(ed1, ed2 *Edits) bool {
	urs1 := ed1.Entries()
	prev := urs1[0]
	if !urIsLetterInsert(prev) {
		return false
	}
	for i := 1; i < len(urs1); i++ {
		e := urs1[i]
		if !urIsLetterInsert(e) {
			return false
		}
		if !urConsecutive(prev, e) {
			return false
		}
		prev = e
	}
	urs2 := ed2.Entries()
	for i := 0; i < len(urs2); i++ {
		e := urs2[i]
		if !urIsLetterInsert(e) {
			return false
		}
		if !urConsecutive(prev, e) {
			return false
		}
		prev = e
	}
	return true
}

