func consecutiveSpaces(ed1, ed2 *Edits) bool {
	urs1 := ed1.Entries()
	prev := urs1[0]
	if !urIsSpace(prev) {
		return false
	}
	for i := 1; i < len(urs1); i++ {
		e := urs1[i]
		if !urIsSpace(e) {
			return false
		}
		if !urConsecutiveEitherSide(prev, e) {
			return false
		}
		prev = e
	}
	urs2 := ed2.Entries()
	for i := 0; i < len(urs2); i++ {
		e := urs2[i]
		if !urIsSpace(e) {
			return false
		}
		if !urConsecutiveEitherSide(prev, e) {
